quests[9265] = { id = 9265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of the Undercity", description = "The Scourge is camped upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", objectives = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles nearby their encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9266] = { id = 9266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Amends", progress = "You must've done something really bad to us or our friends, {name}.  At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold.  With so many of us goblins coming from other cities, we could use a hand keeping warm.  Bring me some runecloth and coal and I'll put in the good word for ya.  Be warned though, our enemies are not going to take kindly to your helping us.", completion = "Thank you, {name}.  You're on a quick path to redeeming yourself with our fair town." }
quests[9267] = { id = 9267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Old Wounds", progress = "You'd better think twice before setting foot in Ratchet, {name}!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", completion = "I'm happy you're seeing the error of your ways, {name}.  Keep the supplies coming; we're not going to forget about you so easily, mister!" }
quests[9268] = { id = 9268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War at Sea", progress = "You seek to befriend the goblins of Tanaris once again, {name}?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", completion = "Keep it coming, {name}.  Us goblins don't forget that easily!" }
quests[9269] = { id = 9269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9270] = { id = 9270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice...", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9271] = { id = 9271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9272] = { id = 9272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing the Part", sourceObjective = "Yarrr... if ye be keen on enjoying the company of us experienced sea dogs, you'd best belay dressing like a blaggard!  Here, put on something proper 'fore I keelhaul yer hide.\n\nThese'll fit ye better than they ever fit that old dog, Red-Eyed Ben.  Lost him in a devil of a storm at sea.\n\nWear 'em with pride, mate!", sourceObjectiveStatus = "unverified-source-field" }
quests[9273] = { id = 9273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Prize Voucher" }
quests[9292] = { id = 9292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.", progress = "Is there something you need?", completion = "Hm, you took this from the corpse of one of the invading abominations?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they wanted to create one inside Stormwind. It is good that they were unsuccessful.", objectives = "Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9295] = { id = 9295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letter from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", objectives = "Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9296] = { id = 9296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", sourceObjective = "Deliver the Dim Necrotic Stone to SOMEONE.", sourceObjectiveStatus = "unverified-source-field" }
quests[9297] = { id = 9297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", sourceObjective = "Deliver the Dim Necrotic Stone to SOMEONE.", sourceObjectiveStatus = "unverified-source-field" }
quests[9298] = { id = 9298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", sourceObjective = "Deliver the Dim Necrotic Stone to SOMEONE.", sourceObjectiveStatus = "unverified-source-field" }
quests[9299] = { id = 9299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Note from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", objectives = "Take the Careworn Note to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9300] = { id = 9300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Page from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", objectives = "Take the Ragged Page to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9301] = { id = 9301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envelope from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", objectives = "Take the Bloodstained Envelope to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9302] = { id = 9302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", objectives = "Take the Crumpled Missive to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9304] = { id = 9304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Document from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last.", objectives = "Take the Smudged Document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9310] = { id = 9310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal that is faintly radiating necrotic energy.", progress = "Can I help you with something?", completion = "You say this was taken from a wight attacking the city?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they were trying to create one in the Undercity. We will have to be vigilant in the future.", objectives = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9317] = { id = 9317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
quests[9318] = { id = 9318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
quests[9319] = { id = 9319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in Dark Places", description = "We are not the only ones who celebrate this holiday, {name}. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.", completion = "Your essence sings with the energy of the flames you found, {name}. The fire you encountered is potent, and with the right knowledge, its power can be harnessed...\n\n\n\nAh! Here we are. May this light your path, no matter where you tread.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9320] = { id = 9320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mana Potion", progress = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9321] = { id = 9321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Healing Potion", progress = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9322] = { id = 9322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Fires in Kalimdor", description = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.\n\nMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.", completion = "Your spirit glows with the warmth of the Kalimdor fires, friend. Is the heat not invigorating?\n\n Once the power fades from you, perhaps these will help rekindle the feeling.", objectives = "Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9323] = { id = 9323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Fires in the Eastern Kingdoms", description = "Our celebration of the flame is spread throughout the land, {class}. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.\n\nYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.\n\n Return once your journey is done.", completion = "Ah, here you are. A little wearier, a bit dustier, but enlightened! The heat touches us all during this season and unites us; your very being glows with the power of the fires you touched.\n\nAh, but these days enlightenment is taken as a rather poor reward for being sent on a task, I suppose. Take these, then, and enjoy the celebration.", objectives = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9324] = { id = 9324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Orgrimmar's Flame", description = "This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "What's this? Unless I'm mistaken, this flame has been taken from the heart of Orgrimmar itself! The fierce hearts of the orcs and trolls are reflected in its searing heat. What a fine addition to our collection--how brave you are, stealing into the enemy's lair to retrieve the sacred flame!\n\nI wonder what power lurks in the other cities...", objectives = "Return the Flame of Orgrimmar to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9325] = { id = 9325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Thunder Bluff's Flame", description = "This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "Unless I miss my guess, this fire has been taken from the cliffs of Thunder Bluff! How it sings with the power of the spirits! You are quite the thief, {name}. Take this as just payment for your skill. Now, if only we had the flames of all three cities...", objectives = "Return the Flame of Thunder Bluff to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9326] = { id = 9326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Undercity's Flame", description = "This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "Hm... what a strange fire! It is subdued, nearly smoldering, but the heat is intense. And you received this from the Undercity, you say? Fascinating. With the flames of all three cities, who knows what we could accomplish?", objectives = "Return the Flame of the Undercity to the Festival Loremaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9330] = { id = 9330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Stormwind's Flame", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "And this brightly-burning fire... you say it came from Stormwind? Remarkable! That must have been quite an adventure! I'll pay you for this, of course. If you find anything else like this, be sure to speak with me again.", objectives = "Return the Flame of Stormwind to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9331] = { id = 9331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Ironforge's Flame", description = "This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "This hearty flame must be from the halls of Ironforge; it's as stalwart as the dwarves themselves. A fine catch, {name}. If I had the fires of the other cities... ah, but never mind. Here is your payment.", objectives = "Return the Flame of Ironforge to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9332] = { id = 9332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Darnassus's Flame", description = "This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire aches of ancient sorrow, {name}. You pulled this from the roots of Teldrassil, you say? Fascinating! Here is a reward for your skill. Return to me should you find anything else like this; I may have a use for it.", objectives = "Return the Flame of Darnassus to the Festival Talespinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9333] = { id = 9333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Gloves", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
quests[9334] = { id = 9334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Wizard Oil", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
quests[9335] = { id = 9335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Sharpening Stones", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
quests[9336] = { id = 9336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Healing Potion", progress = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9337] = { id = 9337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mana Potion", progress = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
quests[9338] = { id = 9338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to Cenarion Circle", progress = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", completion = "You honor us, {name}.  With your continued efforts we will overcome all obstacles." }
quests[9339] = { id = 9339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", sourceObjective = "Return the Flame of Stormwind to (NAME).", completion = "You've proven yourself today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[9341] = { id = 9341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of the Argent Dawn", progress = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", completion = "Take this tabard and wear it proudly. Perhaps your deeds might inspire others to take up arms in support of our fight against the Scourge." }
quests[9343] = { id = 9343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of the Argent Dawn", progress = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", completion = "Take this tabard and wear it proudly. Perhaps your deeds might inspire others to take up arms in support of our fight against the Scourge." }
quests[9353] = { id = 9353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Gift Box Voucher" }
quests[9362] = { id = 9362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Krellian", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.", progress = "There is not time to waste!  Have you the shell?", completion = "I must say, this shell has a strange aura.  It seems only fitting that part of your reward for retrieving it would be to test its magical capabilities...", objectives = "Retrieve the Prismatic Shell for Archmage Xylem. The Archmage resides in a tower atop the cliffs of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9364] = { id = 9364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmented Magic", description = "My research has revealed a unique purpose for the prismatic shell.\n\nCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.\n\nWhen the shell is full, return it to me.", progress = "Have you collected the magic?", completion = "Splendid!  Splendid!\n\nNow we are able to reform this magic into a new spell.  Behold!", objectives = "Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later. When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9365] = { id = 9365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", sourceObjective = "Return the Flame of Stormwind to (NAME).", completion = "You've proven yourself today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[9367] = { id = 9367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", progress = "Are the fires burning?", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem.", objectives = "Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9368] = { id = 9368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", progress = "Are the fires burning?", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem.", objectives = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9386] = { id = 9386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in Dark Places", description = "An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.\n\nSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, {name}.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9388] = { id = 9388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in Kalimdor", description = "There are many flames burning throughout the world today, {name}. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.", progress = "The fires cannot die until the festival is done!", completion = "Ahhh, so they do still burn. I am glad; it would not do for those fires to burn out before their time. You have done well, {name}. Take this with my blessing.", objectives = "Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9389] = { id = 9389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.", progress = "Have you seen to your task?", completion = "So you've returned, and you've seen to the emerald flames of the continent. What do you think, mm? A rare and wonderful sight, to be certain. I am aware, however, that tangible rewards are better appreciated... so please, take this for your trouble.", objectives = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you.", objectives = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", completion = "It's good that you're hear, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up.", objectives = "Speak with General Kirika at the Horde encampment near Hive'Regal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.", progress = "Be careful out there, but also be quick. We have no time to lose.", completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde.", objectives = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring the Desert", description = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.", progress = "Be wary of the dangers of the desert, {name}. With the Alliance lurking in the dunes, any step could be your last.", completion = "You've done well, {name}. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss.", objectives = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Victor...", description = "You've no doubt been fighting long and hard among the towers, {race}. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.\n\nWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.", sourceObjective = "Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing New Outposts", description = "Welcome to the Plaguelands, {name}. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.\n\nTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.", completion = "Very good, {name}. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering Our Defenses", description = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.", completion = "This is good news, {name}. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of the Lovers", description = "An incubus will be drawn to the hearts of lovers, and the most aching love will create the most irresistible lure.\n\nMy scrying has revealed two that should serve exceptionally.\n\nIn Silverpine Forest, Avelina Lilly provides her tailoring services to the fallen wizards at Ambermill. In the Barrens, Isaac Pearson hopes to make his mark in the seaside town of Ratchet.\n\nThey toil on opposite ends of the world, yet their hearts yearn only for each other. Bring those hearts to Carendin.", sourceObjective = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", progress = "Ah, {name}, you return. Were you able to procure the lovers' hearts?", completion = "As expected. Excellently done, {name}.\n\n\n\nIdiots.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come at last. Bring the hearts to the summoning circle below. Place them at its center and call forth the incubus.\n\nThe demon will not be pleased when it realizes that you have tempted it into a trap. Do not fall prey to its beguilement, {name}. You must subdue it fully.\n\nOnly then can I teach you the spell to bind it to your will.", sourceObjective = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", progress = "The incubus possesses martial prowess, but its illusory charms are its most potent weapon. Falter for even a moment, and the demon will seize upon the opportunity to enthrall you.\n\nDo not let it, {name}.", completion = "Impressive. Very impressive. The sayaad specialize in preying upon mortals. Many a {class} has thought themselves strong enough to command one, only to find themselves being commanded instead.\n\nThis trial did not break you, {name}, and your efforts have earned your reward. I will teach you the spell to summon the incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Hurts", description = "A sayaad male is known as an incubus. A creature of profound evil and singular mind.\n\nThe demon must be lured into our world with an item of enticement - an object that represents great love and devotion.\n\nIf you trust a blind man to lead you, {name}, then listen. East from the Cleft of Shadow, along the main drag of Orgrimmar, lives Magar. He longs for the return of his mate, Krilge.\n\nSeek him out. He'll ask you to search for something precious. That is the key which you must bring to Gan'rul.", sourceObjective = "Speak with Magar in Orgrimmar.", completion = "Who told you about Krilge? Have you come with any news? You better not be toying with me...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Love?", description = "You will need a powerful reagent to tempt an incubus -- an object that represents great devotion and love.\n\nWith my scrying, I have located a small figurine that should be suitable for your ritual.\n\nThousands of years ago, the figurine belonged to a young couple. The original owners are no more, but their keepsake has survived to the present day.\n\nFollow the road north into Ashenvale, then west and past Maestra's Post. You will see a house nestled amongst the trees. There you will find what you seek.", sourceObjective = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", progress = "You've returned. Successfully, I assume?", completion = "<Gakin turns the wooden figurine over in his hand.>\n\nI sense the emotional energy residing within this artifact, undiminished by the passing of time. The incubus will be drawn to it like a fly to honey.\n\nTakar never disappoints.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come. Take the figurine and descend into the crypts below. A summoning circle has been prepared, and you must place the figurine at its center.\n\nThen the gateway will open, and the incubus will cross into our world.\n\nA sayaad is not to be underestimated. The demon will not hesitate to attack when it realizes your ruse. You must draw upon all you have been taught to defeat it.\n\nIf you succeed, return to me and I shall bind the creature to your will. Fail, and your soul is forfeit.", sourceObjective = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", progress = "The incubus will try to lower your guard through beguilement and deception. The demon is adept at swaying the hearts of mortals.\n\nRemember that anything it may offer you is false. To the demon, you are merely prey.", completion = "Not bad, {name}. Your have bested the fiend, and your will remains unbroken.\n\nMany a {class} has believed themselves strong enough to bind a sayaad, only to become the demon's next meal instead. I am pleased to see you are not so foolish.\n\nWatch closely, and I will teach you the invocation to call upon your newly bound incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Yes... I see. I feel the residual emotions bound within these threads. Love is woven into its stitches. The incubus will not be able to resist.\n\nTake this to the summoning circle in Neeru's tent, {name}. Summon forth a malevolent incubus, then show it your mastery. Do not expect it to be subdued quietly. Ready your magic and prepare yourself for a fight. Underestimating a demon has been many a warlock's final mistake.\n\nWhen you have defeated it, return the cloth to me. I will let Magar know what you found.", sourceObjective = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", progress = "The sayaad are dominators of minds and torturers of souls. Their visage brings the heart joy, leaving you defenseless when they rend your flesh with whip and claw.\n\nDo not entertain the incubus' charms, {name}. Slay it quickly and let it be done.", completion = "Hah! Victorious, as expected!\n\nThe incubus is subdued, and it will be my pleasure to teach you to summon the demon. You strength is growing, and I have no doubt that this is a mere stepping stone to even greater powers.\n\nI will return the scarf to Magar. I have known that orc for many years, and never did I think he would care for someone the way he cared for Krilge.\n\nIt is a reminder of what separates us from the demons. We wield their darkness, but they will never wield us.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wish You Were Here", description = "I met Krilge while making Mooncloth in Ashenvale. He was stationed there to protect civilians from danger, until he disappeared...\n\nThey've stopped looking for him and consider him a deserter, but I don't believe it.\n\nWe would often meet at Fallen Sky Lake before it became overrun by those aggressive bog beasts.\n\nI'm not typically one to ask favors, but if you could go to Ashenvale and look for any sign of him, I'd appreciate it.", sourceObjective = "Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", progress = "Yes, what is it?", completion = "What is it you have there, {name}? A scarf made of... Mooncloth? You best not be seeking to romance me.", sourceObjectiveStatus = "unverified-source-field" }
quests[66294] = { id = 66294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book of Deathstones", description = "You open the aged and weathered tome and discover text detailing a necromantic ritual. Perhaps Archmage Tarsis would be interested in having this information.", sourceObjective = "Take the Book of Deathstones to Archmage Tarsis Kir-Moldir in Naxxramas.", sourceObjectiveStatus = "unverified-source-field" }
quests[76156] = { id = 76156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk With The Earthmother", description = "I sense in you a hidden talent for the subtle arts, shaman.  Use this mask to infilrate the nearby Venture Company mine and steal their supplies.  It may not seem like a convincing disguise, but a skilled rogue can slip past any guard with naught but a winning smile and a cunning distraction.  I believe this capability lies within you as well.", sourceObjective = "Sneak into the Venture Company mine southeast of Thunder Bluff and collect 5 Seaforium Mining Charges from carts of blasting supplies, then return them to Boarton Shadetotem in Thunder Bluff.", progress = "We'll need to work on your stealth skills, {class}.  I heard you approaching as soon as you set foot on the mesa.", completion = "Hmm... perhaps disguises are not your strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[76160] = { id = 76160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk With The Earthmother", description = "I speak to you from your future, when the Horde faces threats you cannot imagine.  Since the others cannot see me, I rely on you to learn my skills and pass them to the tribe.\n\nMaybe your skills lie with poisons, not disguises.  The Harpies to the north nest in a tree which produces a resin of potent toxicity.  Gather the fallen cones around the nests, then crush them into a salve.  When applied to a blade this salve will sear your opponent's wounds into their flesh and turn their blood to salt.", sourceObjective = "Gather 8 Windfury Cones north of Thunder Bluff, use them with the Mortar and Pestle, then return to Boarton Shadetotem in Thunder Bluff with the result.", progress = "Be careful with the salve once you are finished, {class}.  Even skin contact could be quite painful.", completion = "{class}, this is not the venomous salve I asked for.  What you have brought me is pine nut butter.  Are you sure you followed my instructions?\n\nThis will be of far more use spread on some spice bread than on a dagger.  Although you would be quite formidable against a foe with a nut allergy.", sourceObjectiveStatus = "unverified-source-field" }
quests[76240] = { id = 76240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk With The Earthmother", description = "I have one last idea that may lead us to success.  I still feel there is hidden talent in you, but let us try and coax it out with a less direct approach.\n\nGo and procure a Raw Brilliant Smallfish, then bring it back here.  Use these daggers to clean and fillet it.  Do not think too hard - do what comes naturally.", sourceObjective = "Buy or catch a Raw Brilliant Smallfish, then use the Knife Set to fillet it in front of Boarton Shadetotem in Thunder Bluff.", progress = "Do you have something for me?", completion = "That was quite a display, {class}.  Not the rogueish precision I hoped for, but you possess an impressive ambidexterity.\n\nI see now that you will not be the one to train my people in the subtle arts, but there is one thing I can teach you.  Good luck on your travels, {class}.  The Horde will need heroes like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[77568] = { id = 77568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Strength", description = "A hunter draws strength from their connection and respect for all creatures, not just their pets. You will hunt and slay many beasts in service to the Alliance, but even in battle you must respect your foe.\n\nMy previous apprentice used a mystical rune to augment her skills, but foolishly attempted to practice on the largest of the spiders in the cave to the north, a creature we have named Githyiss the Vile. Her disrespect led to her demise.\n\nSlay Githyiss - but do not underestimate its strength.", sourceObjective = "Defeat Githyiss the Vile in Shadowthread Cave and recover the lost rune. Learn the rune, then report back to Ayanna Everstride in Shadowglen.", progress = "When you have slain Githyiss, recover the rune and learn its magic.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77571] = { id = 77571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Kaldorei", description = "The kaldorei are an ancient people, and our lost relics can be found across Azeroth. Through these relics, the spirits can teach you ways to strengthen your connection to the Dream.\n\nThe grellkin have stolen one such relic. Slay them and retrieve the relic, then follow its guidance to learn a new combat technique. Return to me when you have done this.", sourceObjective = "Recover the relic from the grellkin in Shadowglen. Follow the relic's guidance to learn a new ability, then report back to Mardant Strongoak.", progress = "What has the relic taught you?", completion = "Well done, {name}. Applying the rune you have learned to your equipment will grant you powerful new abilities.\n\nSeek out more of our lost relics along your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[77573] = { id = 77573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second-Story Work", description = "I have prepared a training exercise for you, {name}. There is an idol of an owl on the roof of this building. You should be able to see it from the south entrance. Inside the idol is a hidden compartment containing an engraved rune.\n\nMake your way to the roof, find and memorize the rune hidden in the idol, and return to me.", sourceObjective = "Retrieve the rune from the hidden idol, then use it to learn a new ability. Afterwards, return to Frahun Shadewhisper.", progress = "Have you found the rune?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77574] = { id = 77574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation on Elune", description = "Joining the Alliance has strengthened our people, but we must not forget that we are Kaldorei. Our connection to Elune is at the core of our being.\n\nClear your mind, {name}, and focus on my voice. I will share with you an ancient memory of our kind. Go to the moonwell to the north and kneel in the sacred waters to meditate on Elune's mysteries. Once you have focused your thoughts, you will be able to make sense of this memory and learn a new technique. Return to me when you have done this.", sourceObjective = "Kneel at the moonwell to meditate on Elune, then use the memory to learn a new ability. Afterwards, return to Shanda in Shadowglen.", completion = "Elune will likely grant you more memories along your travels. You can meditate at the moonwells across Azeroth to clear your thoughts and interpret these memories.\n\nUnderstanding more complex visions may require the help of our fellow priests from the Alliance. Do not be afraid to learn from their faith, {name}. Tyrande teaches that the Holy Light worshipped by the humans and the Light of Elune are closely related.", sourceObjectiveStatus = "unverified-source-field" }
quests[77575] = { id = 77575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst the Shadowed Webs", description = "The warriors of the Alliance have much to teach you, but you must also seek out new techniques on your own.\n\nThere is a cave to the north infested by webwood spiders. Another fledgling warrior ventured into the cave some time ago, and never returned. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nFind the rune among the spiders and learn this technique yourself.", sourceObjective = "Slay webwood spiders in Shadowthread Cave and recover the lost rune. Learn the rune, then report back to Alyissia in Shadowglen.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77582] = { id = 77582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trial of Fitness", description = "Above all else, a warrior of the Horde must be of strong body. On your journey, you will undergo many trials of stamina and endurance. \n\nTo this end, I have hidden a cache among the cliffs behind me. You can see it if you stand by the fire in the center of the village. Reaching it will be no easy feat. Within the cache is a rune of great power.\n\nYour test is to find this rune, and return when you have learned its secrets.", sourceObjective = "Find the Hidden Cache in the cliffs behind Frang. Learn the rune inside, then report back to Frang in the Valley of Trials.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77583] = { id = 77583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atop the Cliffs", description = "I have prepared a training exercise for you, {name}. I have hidden a cache among the cliffs nearby. You can see it if you stand by the fire in the center of the village. Within the cache is a rune of great power.\n\nYour test is to acquire this rune, and return when you have learned its secrets.", sourceObjective = "Find the Hidden Cache in the cliffs surrounding the Valley of Trials. Learn the rune inside, then report back to Rwag in The Den.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77584] = { id = 77584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt for the Rune", description = "A hunter draws strength from their connection to the natural world. On your journey, you will track quarry through all manner of harsh terrain, surviving only by your wits.\n\nNot long ago, another fledgling hunter sadly failed in this. He went out to hunt scorpids, and never returned. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nFind his rune among the scorpids nearby, and return when you have learned its secrets.", sourceObjective = "Find the lost rune by slaying scorpids in the Valley of Trials. Learn the rune's power, then report back to Jen'sahn.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77585] = { id = 77585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icons of Power", description = "Shamanism is an ancient practice, {name}. Many artifacts, full of spiritual energy, can be found across Azeroth. I had recently discovered an icon of notable power myself, but it was stolen by those pesky scorpids.\n\nOne of them is likely carrying it around, thinking it a shiny curio to be used as a decoration for their nest. \n\nWhen you find the icon, learn its power and return to me.", sourceObjective = "Find the stolen icon by slaying scorpids in the Valley of Trials. Learn its power, then report back to Shikrik.", progress = "Have you found the icon, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77586] = { id = 77586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Power", description = "I've been experimenting with a new type of magic - a rune which can channel fel energies to fuel powerful spells. I would share this power with you, but it was stolen by one of those pesky Burning Blade familiars.\n\nGo to their coven, to the north, and see if you can find my rune stashed among their possessions. In my experience, the familiars tend to hide their plunder in hard to find places. \n\nOnce you find the rune, learn its magic and report back to me. I would like to see my experiment put to us", sourceObjective = "Find the stolen rune inside of the Burning Blade Coven. Learn its power, then report back to Nartok in The Den.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77587] = { id = 77587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icons of Power", description = "Shamanism is an ancient practice, {name}. Many artifacts, full of spiritual energy, can be found across Azeroth. I had recently discovered an icon of notable power myself, but it was stolen by those pesky scorpids.\n\nOne of them is likely carrying it around, thinking it a shiny curio to be used as a decoration for their nest. \n\nWhen you find the icon, learn its power and return to me.", sourceObjective = "Find the stolen icon by slaying scorpids in the Valley of Trials. Learn its power, then report back to Shikrik.", progress = "Have you found the icon, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77588] = { id = 77588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trial of Fitness", description = "Above all else, a warrior of the Horde must be of strong body. On your journey, you will undergo many trials of stamina and endurance. \n\nTo this end, I have hidden a cache among the cliffs behind me. You can see it if you stand by the fire in the center of the village. Reaching it will be no easy feat. Within the cache is a rune of great power.\n\nYour test is to find this rune, and return when you have learned its secrets.", sourceObjective = "Find the Hidden Cache in the cliffs behind Frang. Learn the rune inside, then report back to Frang in the Valley of Trials.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77590] = { id = 77590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rugged Terrain", description = "A hunter draws strength from their connection to the natural world. On your journey, you will track quarry through all manner of harsh terrain, surviving only by your wits.\n\nNot long ago, another fledgling hunter sadly failed in this. He went out to hunt scorpids, and never returned. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nFind his rune among the scorpids nearby, and return when you have learned its secrets.", sourceObjective = "Find the lost rune by slaying scorpids in the Valley of Trials. Learn the rune's power, then report back to Jen'sahn.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77592] = { id = 77592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atop the Cliffs", description = "I have prepared a training exercise for you, {name}. I have hidden a cache among the cliffs nearby. You can see it if you stand by the fire in the center of the village. Within the cache is a rune of great power.\n\nYour test is to acquire this rune, and return when you have learned its secrets.", sourceObjective = "Find the Hidden Cache in the cliffs surrounding the Valley of Trials. Learn the rune inside, then report back to Rwag in The Den.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77616] = { id = 77616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Rune", description = "The warriors of the Alliance have much to teach you, but you must also seek out new techniques on your own.\n\nAnother young warrior recently ventured into the Echo Ridge Mine. She was experimenting with engraving mystical runes onto her equipment to improve her combat prowess.\n\nI suspect she was overwhelmed when the kobolds captured the mine. Find the rune among the kobolds and learn this technique yourself.", sourceObjective = "Find the lost rune within Echo Ridge Mine and use it to learn a new ability, then report back to Llane Beshere in Northshire.", progress = "Did you find the rune?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77617] = { id = 77617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Light", description = "Relics of the Light can be found across Azeroth. These relics - in particular, the Librams that have guided our order since its founding - can help you strengthen your connection to the Light.\n\nOne such libram was held in the Abbey's archives, but it has been stolen by the Defias bandits to the east. Recover the libram, then study it and follow its guidance to learn a new combat technique. Return to me when you have done this.", sourceObjective = "Recover the libram and follow its guidance to learn a new ability, then return to Brother Sammuel in Northshire.", progress = "What has the libram revealed to you, {name}?", completion = "Well done, {name}. Applying the rune you have learned to your equipment will grant you powerful new abilities.\n\nSeek out more of these relics along your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[77618] = { id = 77618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrice Stolen", description = "I'm ashamed to admit it, {name}, but those Defias jerks got the drop on me. They stole a magical rune I... uh, 'borrowed' from the Abbey's archives. I figured it would give me some kinda advantage in a fix, but I couldn't crack how to make it work.\n\nMake your way east and see if you can snatch it back from their stash, would ya? And try to use the rune yourself, when you find it. You seem like a bookish sort. No offense.", sourceObjective = "Recover the lost rune from the Defias camps and use it to learn a new ability, then return to Jorik Kerridan in Northshire.", progress = "Any luck, {name}?", completion = "A fine bit of larceny there, {name}. Consider that rune a present from yours truly.\n\nIf Brother Paxton asks, we never had this conversation, yeah?", sourceObjectiveStatus = "unverified-source-field" }
quests[77619] = { id = 77619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation on the Light", description = "The Light has shown me your future, fighting the kobolds in Echo Ridge Mine. Within the mine, the Light will grant you a memory of the past. Once this is revealed to you, return to the Abbey and kneel within these halls to meditate on the Light's mysteries.\n\nOnce you have focused your thoughts, you will be able to make sense of this memory and learn a new technique. Return to me when you have done this.", sourceObjective = "Slay kobolds in Echo Ridge Mine to receive a memory. Kneel within Northshire Abbey to meditate on the light, then use the memory to learn a new ability. Afterwards, return to Priestess Anetta.", progress = "What has the Light revealed to you?", completion = "As the Light reveals more visions to you, you can always meditate at sacred sites to clear your thoughts and contemplate these mysteries.\n\nI have also foreseen that your path will lead you to commune with our elven allies in Kalimdor. Learning more about their curious moon-worship rituals may help us someday lead them to the Light as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[77620] = { id = 77620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spell Research", description = "I will teach you what I can, {name}, but your own research will lead to astonishing power. Studying notes left by Azeroth's greatest archmages is an excellent place to start. The Abbey's archives used to contain a myriad of arcane research notes, but they were stolen by Defias agents.\n\nRecover spell notes from the bandits to the east and use this primer to decipher them. Return to me once your research is successful.", sourceObjective = "Recover research notes from the Defias bandits and use them to learn a new spell, then return to Khelden Bremen in Northshire.", progress = "How is your research progressing?", completion = "Well done, {name}. Take these Comprehension Charms. They will help you decipher any more arcane writings you find.\n\nContinue to seek out spell notes across Azeroth and use them to further your research. If you need more charms, pay a visit to a reagent vendor.", sourceObjectiveStatus = "unverified-source-field" }
quests[77621] = { id = 77621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Power", description = "I've been experimenting with a new type of magic - a rune which can channel fel energies to fuel powerful spells. I would share this power with you, but my notes were stolen last night. I suspect the bandits calling themselves the 'Defias' are to blame.\n\nGo to the east, and see if you can find my rune stashed among their possessions. Learn its magic, and report back to me. I would like to see my experiment put to use.", sourceObjective = "Recover the rune from the Defias camps to the east and use it to learn a new ability, then return to Drusilla La Salle in Northshire.", progress = "Well? Any progress?", completion = "You seem to have taken well to this new magic, {name}. Find more runes like this and engrave them to your equipment to wield new abilities against those who would oppose you.\n\nSomeday, perhaps your power will even eclipse my own.", sourceObjectiveStatus = "unverified-source-field" }
quests[77642] = { id = 77642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom of the Loa", description = "Joining the Horde has given our people a safe home, {name}, but we must remember that it is the Loa who are always watching over us.\n\nNow, clear your mind, and I will share an ancient memory with you. Go to the Loa Altar in Sen'jin Village, and kneel before it to commune with the great Loa spirit. Once you have received the Loa's wisdom, you will come to understand the memory I have given you. Through this understanding, you will discover a new power.\n\nReturn to me once you have done this.", sourceObjective = "Kneel at the Loa Altar in Sen'jin Village. Commune with the Loa spirit, then use the memory to learn a new ability. Afterwards, return to Ken'jai  in the Valley of Trails.", progress = "What have the Loa taught you, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThe Loa will grant you many more memories along your journey. You can pray at Loa Altars across Azeroth to clear your thoughts and interpret them, as you have just done.\n\nUnderstanding more complex visions may require the help of fellow priests within the Horde. Do not be afraid to learn from their faith, {name}. The wisdom of the Loa can be found in all things.", sourceObjectiveStatus = "unverified-source-field" }
quests[77643] = { id = 77643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spell Research", description = "As a mage, researching the arcane will lead you to astonishing power. Studying notes left by Azeroth's greatest mages is an excellent place to start. I had recently discovered some myself, but they were stolen by those pesky Burning Blade Familiars.\n\nRecover the spell notes from the coven to the north and use this primer to decipher them. Return when your research is successful.", sourceObjective = "Find the stolen spell notes inside the Burning Blade Coven, then use them to learn a new ability. Afterwards, return to Mai'ah in the Valley of Trails.", progress = "How is your research progressing, {name}?", completion = "Well done, {name}. Take these Comprehension Charms. They will help you decipher any more arcane writings you find.\n\nContinue to seek out spell notes across Azeroth and use them to further your research. If you need more charms, pay a visit to a reagent vendor.", sourceObjectiveStatus = "unverified-source-field" }
quests[77648] = { id = 77648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Tauren", description = "The Tauren are an ancient people, {name}, and our lost relics can be found across Azeroth. Through them, the spirits can teach you ways to strengthen your connection to the Dream.\n\nThe bristleback quilboar have stolen one such relic from us. They have likely stashed it away within Brambleblade Ravine.  Recover the relic, and follow its guidance to learn a new combat technique. Return to me when you have done this.", sourceObjective = "Recover the stolen relic from Brambleblade Ravine. Follow the relic's guidance to learn a new ability, then report back to Gart Mistrunner in Camp Narache.", progress = "What has the relic taught you. {name}?", completion = "Well done, {name}. Applying the rune you have learned to your equipment will grant you powerful new abilities.\n\nSeek out more of our lost relics along your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[77649] = { id = 77649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Strength", description = "Hunters are central to the Tauren way of life, {name}. Our people look to us as both guardians and providers. Many times on your journey, you will alone in hostile territory, surviving only by your wits.\n\nNot long ago, a fledgling hunter was experimenting with mystical runes to improve his combat prowess. He went out to test his new abilities on the Bristleback Battleboars to the east, but never returned.\n\nFind his rune, and use it to learn a new combat technique. Return to me once you have done so.", sourceObjective = "Find the missing rune by slaying Bristleback Battleboars in Brambleblade Ravine. Use the rune to learn a new ability, then report back to Lanka Farshot in Camp Narache.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77651] = { id = 77651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Brambles", description = "The warriors of the Horde have much to teach you, {name}, but you must also seek out new techniques on your own.\n\nAs you may know, there is a group of hostile quilboars to the east. Another fledgling warrior ventured into their territory some time ago, and never returned. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nFind the rune among the quilboar and learn this technique yourself. Return to me when you have done so.", sourceObjective = "Recover the lost rune from Brambleblade Ravine. Use the rune to learn a new ability, then report back to Harutt Thunderhorn in Camp Narache.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77652] = { id = 77652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icons of Power", description = "Shamanism is an ancient practice, {name}. Many artifacts, full of spiritual energy, can be found across Azeroth. I had recently discovered an icon of notable power myself, but it was stolen by the quilboar.\n\nGo to their territory, to the east, and find the stolen icon. It is likely being carried by one of their own shamans attempting to understand its secrets. \n\nOnce you find the icon, learn its power and return to me.", sourceObjective = "Recover the lost icon from the Bristleback Shamans in Brambleblade Ravine. Learn its power, then report back to Harutt Thunderhorn in Camp Narache.", progress = "Have you found the icon, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77655] = { id = 77655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Rune", description = "The warriors of the Alliance have much to teach you, {name}, but you must also seek out new techniques on your own.\n\nThere is a cave full of Frostmane trolls south of here. Another fledgling warrior ventured inside some time ago, but never returned. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nFind the rune among the trolls, one of them is likely carrying it, and learn this technique yourself. Return to me when you have done so.", sourceObjective = "Find the lost rune carried by a  Frostmane troll in Coldridge Valley. Use it to learn a new ability, then report back to Thran Khorman in Anvilmar.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77656] = { id = 77656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Rune", description = "The warriors of the Alliance have much to teach you, {name}, but you must also seek out new techniques on your own.\n\nThere is a cave full of Frostmane trolls south of here. Another fledgling warrior ventured inside some time ago, but never returned. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nFind the rune among the trolls, one of them is likely carrying it, and learn this technique yourself. Return to me when you have done so.", sourceObjective = "Find the lost rune carried by a Frostmane troll in Coldridge Valley. Use it to learn a new ability, then report back to Thran Khorman in Anvilmar.", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77657] = { id = 77657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Light", description = "Relics of the Light can be found across Azeroth. These relics - in particular, the Librams that have guided our order since its founding - can help you strengthen your connection to the Light.\n\nWe held one such libram in our archives, but it was stolen by the Frostmane trolls. The thief is likely still carrying it on them. Recover the libram, and follow its guidance to learn a new combat technique. Return to me when you have done this.", sourceObjective = "Recover the stolen libram carried by a Frostmane troll in Coldridge Valley. Follow its guidance to learn a new ability, then return to Bromos Grummner in Anvilmar.", progress = "What has the libram revealed to you, {name}?", completion = "Well done, {name}. Applying the rune you have learned to your equipment will grant you powerful new abilities.\n\nSeek out more of these relics along your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[77658] = { id = 77658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrice Stolen", description = "I'm ashamed to admit it, {name}, but those Frostmane buggers got the drop on me. They stole a magical rune I... uh, 'borrowed' from the treasury. I figured it would give me a leg up, so to speak, but I couldn't crack how to make it work.\n\nGo to their cave in the south, and see if you can snatch it back from their stash, would ya? When you find it, try to use the rune yourself. You seem like a bookish sort. No offense.", sourceObjective = "Recover the stolen rune from the cave of Frostmane trolls in Coldridge Valley. Use it to learn a new ability, then return to Solm Hargrin in Anvilmar.", completion = "A fine bit of larceny there, {name}. Consider that rune a present from yours truly.\n\nIf anyone asks, we never had this conversation, yeah?", sourceObjectiveStatus = "unverified-source-field" }
quests[77659] = { id = 77659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrice Stolen", description = "I'm ashamed to admit it, {name}, but those Frostmane buggers got the drop on me. They stole a magical rune I... uh, 'borrowed' from the treasury. I figured it would give me a leg up, so to speak, but I couldn't crack how to make it work.\n\nGo to their cave in the south, and see if you can snatch it back from their stash, would ya? When you find it, try to use the rune yourself. You seem like a bookish sort. No offense.", sourceObjective = "Recover the stolen rune from the cave of Frostmane trolls in Coldridge Valley. Use it to learn a new ability, then return to Solm Hargrin in Anvilmar.", completion = "A fine bit of larceny there, {name}. Consider that rune a present from yours truly.\n\nIf anyone asks, we never had this conversation, yeah?", sourceObjectiveStatus = "unverified-source-field" }
quests[77660] = { id = 77660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trek Through the Caves", description = "Hunters are a hardy lot, {name}, even among Dwarves. We set out across Azeroth to explore lands unknown, and hunt all sort of dangerous and exotic quarry. Many times on your journey, you will find yourself alone in hostile territory, surviving only by your wits.\n\nThe Frostmane trolls have stolen a rune of great power from us. They have likely stashed it away in their cave to the south. Recover the rune, and use it to learn a new combat technique. Return to me once you have done so.", sourceObjective = "Recover the stolen rune from the cave of Frostmane trolls in Coldridge Valley. Use the rune to learn a new ability, then report back to Thorgas Grimson in Anvilmar.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77661] = { id = 77661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation on the Light", description = "The Light has shown me your future, {name}, fighting the Troggs to the southwest. Within a chest, you will find a memory of the past. Once you acquire it, return here and kneel before the Altar of the Light. Meditate on its mysteries.\n\nWhen you have focused your thoughts, you will be able to make sense of this memory and learn a new technique. Speak to me when you have done this.", sourceObjective = "Find a memory of the past inside of a chest at the trogg camp near Anvilmar. Then, kneel at the Altar of the Light within Anvilmar to meditate on the light, and use the memory to learn a new ability. Afterwards, speak to Branstock Khalder.", progress = "What has the Light revealed to you, {name}?", completion = "As the Light reveals more visions to you, you can always meditate at sacred sites to clear your thoughts and contemplate these mysteries.\n\nI have also foreseen that your path will lead you to commune with our elven allies in Kalimdor. Learning more about their curious moon-worship rituals may help us someday lead them to the Light as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[77666] = { id = 77666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Power", description = "I've been experimenting with a new type of magic - a rune which can channel fel energy to fuel powerful spells. I would share this power with you, but it was stolen by one of those pesky troggs.\n\nThere is a camp of those Rockjaw vermin to the southwest. See if you can find my rune stashed among their possessions, likely in a chest of some kind. Once you find it, learn its magic and report back to me. I would like to see my experiment put to use.", sourceObjective = "Recover the rune from the group of Troggs, southwest of Anvilmar, and use it to learn a new ability. Then, return to Alamar Grimm in Anvilmar.", progress = "Well, {name}? Any progress?", completion = "You seem to have taken well to this new magic, {name}. Find more runes like this and engrave them to your equipment. Wield this power against those who would oppose you.\n\nSomeday, perhaps your power will even eclipse my own.", sourceObjectiveStatus = "unverified-source-field" }
quests[77667] = { id = 77667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spell Research", description = "As a mage, researching the arcane will lead you to astonishing power. Studying notes left by Azeroth's greatest mages is an excellent place to start. I had recently discovered some myself, but they were stolen by those pesky troggs to the southwest.\n\nRecover the spell notes from the troggs' camp and use this primer to make sense of them. Return when your research is successful.", sourceObjective = "Find the stolen spell notes at the trogg camp to the southwest of Anvilmar, then use them to learn a new ability. Afterwards, return to Marryk Nurribit in Anvilmar.", progress = "How is your research progressing, {name}?", completion = "Well done, {name}. Take these Comprehension Charms. They will help you decipher any more arcane writings you find.\n\nContinue to seek out spell notes across Azeroth and use them to further your research. If you need more charms, pay a visit to a reagent vendor.", sourceObjectiveStatus = "unverified-source-field" }
quests[77668] = { id = 77668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Rune", description = "The Dark Lady's warriors have much to teach you, but you must also seek out new techniques on your own.\n\nAnother warrior recently ventured north into Night Web's Hollow. He was experimenting with engraving mystical runes onto his equipment to improve his combat prowess.\n\nI suspect he was overwhelmed by the spiders infesting the mine. Find the rune among their webs and learn this technique yourself.", sourceObjective = "Find the rune hidden in Night Web's Hollow and use it to learn a new technique, then report back to Dannal Stern in Deathknell.", progress = "What have you found?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77669] = { id = 77669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Rune", description = "Who were you in life, {name}? A spy? A thief? A cook who was especially handy with a knife? Whatever your past, it's time to embrace new tactics. The rogues of the Forsaken seize every advantage offered to them.\n\nThe Scarlet Converts to the east fight like they've never seen combat, but the Crusade has issued them mystical runes to enhance their abilities. Steal one of these runes and learn its magic, then return to me.", sourceObjective = "Pickpocket or kill Scarlet Converts to find a rune, then use it to learn a new ability. Afterwards, return to David Trias in Deathknell.", progress = "Have you found the rune, {name}?", completion = "Well done, {name}. Applying the rune to your equipment will grant you powerful new abilities.\n\nThere are many such runes throughout Azeroth. Seek them out, as they will help along your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[77670] = { id = 77670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation on Undeath", description = "I will summon to your mind a memory of the living - it may even be your own memory. Go to the graveyard beside this chapel and find where the chill of death is strongest, then kneel and focus your thoughts. Through focus on the mysteries of undeath you will find clarity in this memory and learn a new technique. Return to me when you have done this.", sourceObjective = "Kneel in the graveyard to meditate on undeath, then use the rune to learn a new ability. Afterwards, return to Dark Cleric Duesten in the Deathknell chapel.", progress = "If you have difficulty focusing on death, you could try dying again. It's unlikely to be permanent the second time either.", completion = "The living cling to the Light for one reason - they fear the oblivion of death. As Forsaken, that fear has no further hold over you. Though the Light now rejects even those among us who were once its most fervent devotees, we command dark powers that lie beyond death's shadow.\n\nAs you grow stronger I recommend spending some time with the trolls of the Horde. Though their culture is primitive, the 'loa' they revere have some connection to undeath. They may provide insight into our nature.", sourceObjectiveStatus = "unverified-source-field" }
quests[77671] = { id = 77671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spell Research", description = "The arcanists of the Royal Apothecary Society commit their unlife to spell research in service to the Forsaken. Adventure may be your calling, but you can serve the Dark Lady by securing and researching spell notes you find in your travels.\n\nKill the Scarlet Crusade initiates camped near Deathknell, and seize their spell notes. Use this primer to decipher the notes and learn a new spell, then return to me.", sourceObjective = "Kill Scarlet Initiates to find spell notes and use them to learn a new ability, then return to Isabella in Deathknell.", progress = "What have you learned, {name}?", completion = "Well done, {name}. Take these Comprehension Charms. They will help you decipher any more arcane writings you find.\n\nContinue to seek out spell notes across Azeroth and use them to further your research. If you need more charms, pay a visit to a reagent vendor.", sourceObjectiveStatus = "unverified-source-field" }
quests[77672] = { id = 77672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Rune", description = "I've been experimenting with a new type of magic - a rune which can channel fel energies to fuel powerful spells. I sent an apprentice to test the rune against the spiders in the mine to the north, but he has not returned. I suspect we will not see him again.\n\nPerhaps you will prove more resilient. Go to the mine and recover the rune from the spiders' webs. Learn its magic, and report back to me.", sourceObjective = "Recover the rune from Night Web's Hollow and use it to learn a new ability, then return to Maximillion in Deathknell.", progress = "What have you found, {name}?", completion = "You seem to have taken well to this new magic, {name}. Find more runes like this and engrave them to your equipment to wield new abilities against those who would oppose you.\n\nSomeday, perhaps your power will even eclipse my own.", sourceObjectiveStatus = "unverified-source-field" }
quests[77690] = { id = 77690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Upgrade", description = "Greetings my esteemed {class} acquaintance! My name is John Trinketman, world renown traveler and puzzle solver! Never heard of me, have you? No matter! I am here in Ironforge looking for two of the most prestigious pieces of jewelry this side of Azeroth has ever seen! It is said they form a puzzle!\n\nUnfortunately, rumor has it that they both reside in the dangerous Blackrock Mountain! Surely an adventurer of your caliber would have no issue finding these pieces for me?", sourceObjective = "Acquire Blackhand's Breathe and the Hand of Justice.", sourceObjectiveStatus = "unverified-source-field" }
quests[78088] = { id = 78088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Artifact", progress = "Did you find something in the tower?", completion = "You were right to bring this to me, {name}." }
quests[78089] = { id = 78089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advice From Stormwind", description = "I sense a dark power within this orb, but its source eludes me. We need advice from the paladins of Stormwind. Bring the orb to them.", sourceObjective = "Consult the paladins of Stormwind for advice on the orb.", progress = "You bring news from Kalimdor?", completion = "<Examines the orb with a worried expression>", sourceObjectiveStatus = "unverified-source-field" }
quests[78090] = { id = 78090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Opinion", description = "I'm not sure what to make of this orb, {name}. I think we will need the help of... a specialist.\n\nWe are aware of a warlock sect operating out of Stormwind. Officially we reject the presence of warlocks in the city. Unofficially, their knowledge can be of use when dealing with demonic forces.\n\nFind a representative of these warlocks, and seek their opinion on the orb.", sourceObjective = "Find the warlock sanctum within Stormwind and seek advice on the orb.", progress = "You're a long way from the cathedral, {class}. I hope you realize you have no authority here.", completion = "So the Silver Hand requires my aid? It will not come cheaply.", sourceObjectiveStatus = "unverified-source-field" }
quests[78091] = { id = 78091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earning Your Salt", description = "I will study the orb and tell you what I learn, but you must first do something for me.\n\nThe warlocks of the Blackrock clan use specially prepared salts to enhance their summoning rituals. Collect some from the orcs in Redridge.\n\nWhen you return, I will share with you the results of my studies.", sourceObjective = "Collect 14 Summoner's Salt from Blackrock Summoners in Redridge Mountains, then return to Ursula Deline in Stormwind.", progress = "<The warlock is studying the orb intently>", completion = "Ah... the salts. I had forgotten all about them.\n\nThis orb is unlike anything I have seen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78092] = { id = 78092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Must Be Destroyed", description = "This orb is indeed connected to a powerful entity, somewhere beyond the Twisting Nether. I cannot divine its nature, but I feel its perception reaching through the orb... studying me in return.\n\nI am reluctant to admit this, {name}, but the orb must be destroyed.\n\nIt seems impervious to most damage, but it may be vulnerable to the weapon of a powerful demon lord. I am unsure where you will find such a weapon, but it remains your best option.\n\nGood luck, {name}.", sourceObjective = "Find a way to destroy the orb.", progress = "<Your hair stands on end as infernal energies surround you>", completion = "<You raise the orb towards the spear>", sourceObjectiveStatus = "unverified-source-field" }
quests[78093] = { id = 78093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Delgren", description = "<The shattered remains of the orb lay at your feet. Delgren will want to see you have succeeded.>", sourceObjective = "Return the Orb Shards to Delgren.", progress = "Did you find a way to destroy the orb?", completion = "This is a relief, {name}. But whatever was watching Azeroth through that orb... I have a feeling they will not be happy it was destroyed.\n\nTake this as my thanks for your efforts. And... be careful.", sourceObjectiveStatus = "unverified-source-field" }
quests[78114] = { id = 78114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Wyvern Wrangling", description = "You seen those Pridewing Wyverns flying around? I bet folks would pay good money to see me do a flip on one of those things!\n\nThey're an ornery bunch, though. Can't get one tame enough to ride; to say nothing of high-flying stunts.\n\nI've heard you can make a special wand to soothe 'em. Could probably even do it myself. All I'd need is a Hypnotic Crystal, and a Gnarled Wand of Wild Magic. \n\nNow, I'm not entirely sure about where to get these, but we can talk details later.", sourceObjective = "Bring a Hypnotic Crystal and a Gnarled Wand of Wild Magic to Jixo Madrocket in the Stonetalon Mountains.", progress = "Any luck with the supplies?", completion = "Nice work! Now it's time for a little field test.", sourceObjectiveStatus = "unverified-source-field" }
quests[78121] = { id = 78121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangling a Wild Wyvern", description = "With the wand made, there's only one thing left to do. I'm gonna tame myself a wyvern! \n\nYou should come with, {name}. You'll have a front row seat to my newest act!", sourceObjective = "Follow Jixo Madrocket, and watch him tame a Wyvern.", completion = "Let me tell ya, {name}, that fall hurt even worse than it looked. I'll be fine, but I don't think Wyvern wrangling is in the cards for old Jixo. \n\nMaybe I should just stick to the hits, y'know? Stunts like jumpin' over a row of twenty gnomes on a chopper. Folks eat that stuff up.\n\nTake the wand. I've got no use for it anymore. And have this too; a little something extra for all the trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[78124] = { id = 78124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nar'thalas Almanac", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78127] = { id = 78127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dalaran Digest", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78132] = { id = 78132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonslayer's Helm", progress = "The helm of the Dragonslayer once belonged to a great commander who fell in battle. It is said his tormented soul still haunts the site of his passing.", completion = "Splendid job, {name}! With this, I am one step further on my path to glory." }
quests[78133] = { id = 78133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonslayer's Shield", progress = "The shield of the Dragonslayer is rumored to be held by an Orcish warlord. He stole it while raiding a human settlement.", completion = "Splendid job, {name}! With this, I am one step further on my path to glory." }
quests[78134] = { id = 78134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonslayer's Lance", progress = "The lance of the Dragonslayer has changed hands many times. Every now and then, rumor spreads of it appearing in black market arms deals. Perhaps the lance's current unsavory proprietor would be willing to part with it; for a price.", completion = "Splendid job, {name}! With this, I am one step further on my path to glory." }
quests[78142] = { id = 78142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewitchments and Glamours", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78143] = { id = 78143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Dreamers", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78144] = { id = 78144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alonso the Dragonslayer", description = "The time is upon us, {name}. I am adorned with armor befitting a true Dragonslayer! You have been of great assistance.\n\nI should ask that you accompany me now, as my honorary squire, and watch me best the great dragon once and for all!", sourceObjective = "Accompany Alonso to slay the dragon.", completion = "I've done it {name}! At last my foe is defeated!\n\nOh the clash of fang and metal; of scale and blade. What peril, what thrill! And through it all, I arise a champion. \n\nLet us not forget your humble contribution as well! Without the armor you retrieved, I surely would not have bested the fiend. \n\nYou have been an excellent squire, {name}. Perhaps, one day, you too shall walk the glorious path of a knight.", sourceObjectiveStatus = "unverified-source-field" }
quests[78145] = { id = 78145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcanic Systems Manual", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78146] = { id = 78146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goaz Scrolls", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78147] = { id = 78147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimes Against Anatomy", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78148] = { id = 78148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes of the Sorceror-Kings", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78149] = { id = 78149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Land", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[78150] = { id = 78150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of the Library", sourceObjective = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[78192] = { id = 78192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Light", description = "So you'd like to learn more about the Light? You've come to the right dwarf! Healin', smitin', protectin', I do it all!\n\nHow about a practical lesson? Head out to Ashenvale and get one over on those Horde zombies acting like they own the place. The Light's good for lots o' things, but blasting the undead is my favorite!", sourceObjective = "Kill 7 Forsaken Herbalists and 9 Forsaken Seekers in northwest Ashenvale, then return to Maethra Slagheart in Darnassus.", completion = "Great job! Nothin' like sizzling a few undead to put you in a religious mood, huh?", sourceObjectiveStatus = "unverified-source-field" }
quests[78193] = { id = 78193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Light", description = "All right, {name}, let's get serious. The Light isn't some goddess you need to impress or a spirit you need to befriend. It's in all of us! All you gotta learn is how to feel it.\n\nTreat yourself to a little trip to Stormwind and visit the Cathedral of Light. It's a great place to take some time to pray and get to know the Light. And that architecture's a sight to see!", sourceObjective = "Travel to Stormwind City and speak to High Priestess Laurena in the Cathedral of Light.", completion = "There is no need to prove yourself, {name}. The Light welcomes all petitioners to its warmth.\n\nFeel free to stay within this sanctuary as long as you like and meditate on the Light's mysteries.", sourceObjectiveStatus = "unverified-source-field" }
quests[78194] = { id = 78194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Elune", description = "It is refreshing to see a {race} take interest in Elune. Though the kaldorei are her favored children, she cares for all the people of Azeroth. In return for her blessings, we care for the land in her name.\n\nI have recently been made aware of a disruption in nature's balance - rabid dire wolves, spotted within Duskwood. Show your respect for Elune's balance by culling their numbers, then return to me with proof of your deeds.", sourceObjective = "Collect 10 Dire Wolf Paws from wolves in Duskwood.", progress = "What news do you bring?", completion = "I thank you, {name}. The balance is stronger for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[78195] = { id = 78195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Elune", description = "The moonwells contain Elune's blessing, but they are also a symbol of the connections we all share. Take this phial of water from Stormwind's moonwell to the one in Auberdine, on the shores of Kalimdor. As the waters combine, so too will your spirit combine with that of the kaldorei.", sourceObjective = "Bring the phial to Syrnoya at the Auberdine moonwell.", completion = "<Syrnoya adds the water of the phial to the moonwell>\n\nElune's favor is with you, {name}. When your travels take you to other moonwells, stop for a moment and you may receive her blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[78196] = { id = 78196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Undeath", description = "If you seek to find 'belief' or 'worship' among the Forsaken priests, you will be disappointed. We have seen beyond death and we know nothing awaits us there. Our faith derives from cold experience, not naive hope.\n\nExperience... that may be what you need. Collect shadeleaf from the swamp creatures of Ashenvale, then return to me. I have an idea that may answer your questions.", sourceObjective = "Collect 12 Shadeleaf from Shadethicket elementals in Ashenvale.", progress = "Have you collected the shadeleaf?", completion = "Wait a moment, and I will prepare something for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[78197] = { id = 78197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Undeath", description = "All Forsaken have experienced the edge of death. To see existence come to an end, with no gods beyond it... it may sound terrifying, but truly it is freeing. Our will is our own, beholden to no forces beyond ourselves.\n\nGo to the graveyard in Brill and drink this tincture. It will take you to the edge of death and hold you there. Face oblivion with determination and you will find your way back to the living. I can think of no better way to share what it means to be Forsaken.", sourceObjective = "Travel to Brill's graveyard in Tirisfal Glades and use the Tincture of Waking Death.", progress = "You try to call out to the spirit healer, but make no sound. Its gaze passes through you without acknowledgement.", completion = "Your terror feels distant as the tincture weakens the bond between your soul and mind. An eternity of nothing stretches before you.\n\nFor an instant you perceive all of Azeroth, present and future. The thread of your fate is pulled from its tapestry and cast aside, leaving no trace. The world continues to turn without notice of your absence.\n\nYou slowly regain your senses as the tincture wears off. Was that... how Forsaken feel all the time?", sourceObjectiveStatus = "unverified-source-field" }
quests[78198] = { id = 78198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Loa", description = "The mighty troll empires of our ancestors were built on the strength of the loa - spirits of great power who rule across Azeroth. We worship many loa in the Darkspear tribe, but if you are interested in sharing our faith, there is one in particular who may be willing to bargain with you.\n\nFirst, you will need to prepare an offering. Travel to Tarren Mill and strike back at the humans who challenge the Horde's claim to the area. Collect the bones of your victims and return to me.", sourceObjective = "Collect 14 Hillsbrad Human Bones from humans in Hillsbrad Foothills, then return to Baj'ura in Undercity.", progress = "How fares the battle against the humans?", completion = "Excellent... these remains will make a fine offering.", sourceObjectiveStatus = "unverified-source-field" }
quests[78199] = { id = 78199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Loa", description = "Take the offering south, to the Echo Isles. Along the island beaches you will find a shrine to Bwonsamdi, the loa of death. An offering from a Forsaken will no doubt attract his attention.\n\nI warn you though, {name}. There's always a price to pay when bargaining with the loa. You may not be aware of what you give up now, but Bwonsamdi always collects his debts in the end.", sourceObjective = "Travel to the Echo Isles and use the offering at Bwonsamdi's shrine.", progress = "The air around you seems to thicken as you place your offering on the pile.", completion = "Your offering bursts into purple flame as a shadow falls across the ground. You see no one, but feel the presence of the loa of death leering behind you.\n\nImages fill your mind. A wall of masks, stretching beyond sight and laughing down at you. A temple in a great swamp, filled with souls of the dead.\n\nAs the vision clears, a laugh echoes in the air...", sourceObjectiveStatus = "unverified-source-field" }
quests[78229] = { id = 78229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of The Owls", description = "Let me see that symbol you carry, {name}. \n\nIt seems you have begun the trial of the owls. This marks a pivotal moment in your journey as a druid.\n\nThere are more symbols like this one; spread across Azeroth. To earn them, you must perform great feats of mind and body alike.\n\nOne owl sits beneath a great tree in the Eastern Kingdoms. Another is near a great tree here in Kalimdor. Yet another is at sea; off the coast of Hillsbrad.\n\nSeek out these owls, {name}, and bring their symbols to me.", sourceObjective = "Bring symbols of the three owls to Loganaar in Moonglade.", progress = "How goes your trial, {name}?", completion = "I would like to congratulate you, {name}. What you've accomplished is no small feat.\n\nTo pass the trial of the owls is to demonstrate an attunement with all aspects of your druidic calling.\n \nTake this rune as a mark of your achievement. I hope it will serve you well as a warden of the Emerald Dream.", sourceObjectiveStatus = "unverified-source-field" }
quests[78261] = { id = 78261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horn of Xelthos", description = "<A note sits in the chest>\n\nHello, {name}.\n\nI desire a treasure known as The Horn of Xelthos, which is somewhere within Shadowfang Keep.\n\nVenturing inside the keep usually calls for backup. However, for this job, a low profile is of utmost importance.\n\nYou must go alone.\n\nI have a contact, by the name of Veenix, in the Stonetalon Mountains. He should be able to help you get past the courtyard gate. The rest is up to you. \n\nReturn the horn here, and your payment will be sent soon after.\n\n- C", sourceObjective = "Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone.", progress = "<The chest sits, empty.>", completion = "<You place The Horn of Xelthos into the chest>", sourceObjectiveStatus = "unverified-source-field" }
quests[78265] = { id = 78265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Oil", progress = "I'm going to need fish oil - and a lot of it!", completion = "Thanks a lot, {name}. I'll put this to good use." }
quests[78266] = { id = 78266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Ordinance", progress = "I'll need some Dark Iron Ordinance. Where are you going to find Dark Iron dwarves? That's your problem!", completion = "Thanks a lot, {name}. I'll put this to good use." }
quests[78267] = { id = 78267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Turbochargers", progress = "I'll need some of the Venture Company's Shredder Turbochargers. They're tightly coupled to the shredder systems, so you'll need special equipment to salvage them.\n\nNo, I don't have that equipment.", completion = "Thanks a lot, {name}. I'll put this to good use." }
quests[78270] = { id = 78270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Lockpicks", description = "<A note sits in the chest>\n\nHello again, {name}.\n\nI desire a treasure known as The Horn of Xelthos, which is somewhere within Shadowfang Keep.\n\nVenturing inside the keep usually calls for backup. However, for this job, a low profile is of utmost importance.\n\nYou must go alone.\n\nI have a contact, by the name of Veenix, in the Stonetalon Mountains. He should be able to help you get past the courtyard gate. The rest is up to you. \n\nReturn the horn here, and your payment will be sent soon after.\n\n- C", sourceObjective = "Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village.", progress = "You said you're breaking into Shadowfang...alone? You've got some guts! \n\nI can hook you up with explosives to get past the gate, but I'll need a work order to make it look legit on the books. An employee around here's likely carrying one. Probably someone who does a lot of tinkering or building.", completion = "Nice job, {name}. I figure that was a cakewalk for someone in your line of work.\n\nAs promised, here's the goods.", sourceObjectiveStatus = "unverified-source-field" }
quests[78277] = { id = 78277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Token of Gratitude", sourceObjective = "It might have been a silly thing to do, but Thule, Gunthar and I were like family... brothers. We never expected our world to be torn apart, nor for Thule to side with the Lich King leaving Gunthar and myself to fight for our humanity... \n\nI can sense the taint of the scourge seeping into Thule's portion of the wand. It will forever be marred, corrupted by his betrayal, but alas I am not ready to let go... maybe with time.\n\nPlease accept this token of knowledge as my final thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[78287] = { id = 78287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Me Make You An Offer", description = "The first run's all packed up, {name}. Take this to Stormwind and get it in front of the higher-ups. Someone who can sign today!", sourceObjective = "Take the Arms Shipment to Master Wood in Stormwind City.", progress = "A delivery from Ratchet? I didn't order anything from Ratchet.", completion = "An arms supplier in Ratchet? Well... the Alliance does need all the supplies we can get. And we don't want the Horde signing a deal. We should act fast.", sourceObjectiveStatus = "unverified-source-field" }
quests[78288] = { id = 78288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Me Make You An Offer", description = "The first run's all packed up, {name}. Take this to Orgrimmar and get it in front of the higher-ups. Someone who can sign today!", sourceObjective = "Take the Arms Shipment to Zel'mak in Orgrimmar.", progress = "A delivery from Ratchet? I didn't order anything from Ratchet.", completion = "An arms supplier in Ratchet? Hmm.. the Horde has been trying to steer Goblin business towards us and away from the Alliance. We should act fast to secure this new opportunity.", sourceObjectiveStatus = "unverified-source-field" }
quests[78297] = { id = 78297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Got Yourself A Deal", description = "I've signed in the appropriate places, {name}. Take this back to Ratchet and inform your supplier that the Alliance is happy to do business.", sourceObjective = "Return the Signed Procurement Contract to Grizzby in Ratchet.", progress = "Did ya close the deal?", completion = "They signed without even negotiating? Ha! Everything's turning around for ol' Grizzby!\n\nAnd you, {name}, you've been a real pal. Here ya go, a little token of my thanks.\n\nAnd now that we're officially in business, feel free to look through my stock of gear and see if anything catches your eye. I'll even give you the employee discount!", sourceObjectiveStatus = "unverified-source-field" }
quests[78304] = { id = 78304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Got Yourself A Deal", description = "I've signed and sealed the contract, {name}. Tell this goblin he now deals exclusively with the Horde.", sourceObjective = "Return the Signed Procurement Contract to Grizzby in Ratchet.", progress = "Did ya close the deal?", completion = "They signed without even negotiating? Ha! Everything's turning around for ol' Grizzby!\n\nAnd you, {name}, you've been a real pal. Here ya go, a little token of my thanks.\n\nAnd now that we're officially in business, feel free to look through my stock of gear and see if anything catches your eye. I'll even give you the employee discount!", sourceObjectiveStatus = "unverified-source-field" }
quests[78307] = { id = 78307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horn of Xelthos", description = "Description", sourceObjective = "Log", completion = "<A note sits in the chest>\n\nFor {name}. I'll be seeing you.\n\n- C", sourceObjectiveStatus = "unverified-source-field" }
quests[78506] = { id = 78506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Distress", description = "Listen, {name}. The corruption I spoke of before goes beyond Baron Aquanis. I've been sensing a certain unease within the elemental world for some time. I fear something is gravely wrong, and the corruption of Baron Aquanis only furthers my suspicions.\n\nFind more of those elementals who are suffering: here in Ashenvale, and in the nearby Stonetalon Mountains. Bring me motes of their essence. Perhaps I can analyze them, and begin to understand the nature of their rage.", sourceObjective = "Collect motes of elemental rage, and bring them to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "The elementals suffer greatly, {name}. I must know why.", completion = "Thank you, {name}. Hopefully these will provide some answers.", sourceObjectiveStatus = "unverified-source-field" }
quests[78537] = { id = 78537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Insight", description = "The motes you gathered are an important clue, {name}, but we will also need some spiritual guidance if we're to fully understand the situation.\n\nThere is a ritual I often practice that requires an Elixir of Insight. The visions it grants will reveal the next steps we must take.\n\nI can brew the elixir from two others. An Elixir of Water Breathing to free the body, and an Elixir of Wisdom to open the mind.\n\nBring these to me, and we can begin the ritual.", sourceObjective = "Bring an Elixir of Water Breathing and an Elixir of Wisdom to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "Have you acquired the component elixirs, {name}?", completion = "Well done. Now the ritual can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[78561] = { id = 78561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir of Insight", description = "The elixir is ready, {name}. Go down to the bonfire, on the beach, and drink it. Heed the vision given to you by the spirits, and return to me with your findings.", sourceObjective = "Drink the Elixir of Insight near the bonfire at Zoram'gar Outpost, and witness the vision it grants you.\n\nProvided item:", progress = "What did the spirits reveal to you, {name}?", completion = "A quilboar {class} ... enslaving elementals? This is certainly troubling.", sourceObjectiveStatus = "unverified-source-field" }
quests[78575] = { id = 78575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirzek", description = "That quilboar you saw in your vision; I believe it was Hirzek. \n\nThe Earthen Ring has known of the Quilboar's crude version of shamanism for some time. However, there are rumors that a few have recently been making troubling strides. Hizrek is one such Quilboar. \n\nFrom what you saw, it seems he is enslaving elementals, rather than cooperating with them as you and I would. No doubt this is causing distress among the elemental plane.\n\nYou must stop him, {name}. For the good of Shamans and elementals alike.", sourceObjective = "Slay Hirzek at Blackthorn Ridge, Barrens, and bring his staff to Jen'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "Hirzek's actions are an insult to the shamanistic ways, and the very elements themselves. He must be stopped.", completion = "<Je'neu takes the staff into his hands.>\n\nYou've done a great deed, {name}. I am relieved to know Hirzek's tortures have come to an end. Though, I fear he may be merely a symptom of a greater disease. So many elementals of Azeroth still call out in anguish.\n\nMany questions remain to be answered; perhaps more than when we started. Nonetheless, I thank you for your service to the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[78611] = { id = 78611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Waylaid Shipment", sourceObjective = "The shipment's missing some items, but it will still be of some use.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78612] = { id = 78612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[78676] = { id = 78676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Bhossca", description = "<A note sits in the chest>\n\nGlad to have you back, {name}.\n\nThe latest object of my desire is an artifact known as the Eye of Bhossca. My sources tell me the eye is somewhere within the Scarlet Monastery. As with Shadowfang Keep, you must infiltrate the monastery alone.\n\nIt may behoove you to find a disguise before going in. It will make getting around a touch easier. I'm sure you could find something on the monastery's grounds.\n\nReturn the eye here, and payment will be delivered as before.\n\n- C", sourceObjective = "Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone.", progress = "<The chest sits, empty.>", completion = "<You place The Eye of Bhossca into the chest>", sourceObjectiveStatus = "unverified-source-field" }
quests[78680] = { id = 78680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumors Abound", description = "Whispers within the shadows speak of a weapon containing the soul of a great demonic being. Lesser demons like Soran'ruk are one thing, but much more powerful entities, bound as punishment for their failures, offer unimaginable power.\n\nThis weapon was lost ages ago, shattered during the Third War.\n\nRecently these rumors have said that mages meddling with dark magic beyond their comprehension have claimed fragments of the weapon, but they are unable to unlock the powers without reforming it.", sourceObjective = "Not much is known about the location of these shattered weapon fragments, save that they are both in the possession of once great mages held up in towers of importance. One is said to be located here to the north on Kalimdor, while the other is nestled near the heart of the Eastern Kingdoms.\n\nSee if the rumors are true... Search for the two missing halves of this weapon and bring them to me.", progress = "Still no signs of the weapon fragments? I guess I've sent you on a fool's errand.", completion = "There's still much that needs to be done before I can reform a weapon of this power. We've started down this path and there's no turning back now.", sourceObjectiveStatus = "unverified-source-field" }
quests[78681] = { id = 78681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conjuring", description = "The demon, Des'Altek, seems to have broken free of it's prison, but its still bound to it like a prisoner to their cell. We must summon forth the demon to capture its soul again.\n\nTo the north, in Ashenvale, where great demons fell, there is a location on the ridge that was once used by the Legion for sacrifices. The ground is permanently scarred from the atrocities that occurred here, but if we can gather the Blood of the Legion from the demons that still infest this land... that's the key.", sourceObjective = "Collect 10 Blood of the Legion and perform the ritual to summon Des'Altek to trap its soul once again.", progress = "Make an offering of blood.", completion = "Use the Dark Ritual Stone to begin the Dark Ritual. There's no turning back now...", sourceObjectiveStatus = "unverified-source-field" }
quests[78684] = { id = 78684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Traveler", description = "What? Where am I? How... how did I get here?\n\n<The man before you stumbles around as if sea sick. His eyes widen and his hands tremble and you stare at each other in a moment of shared confusion.>\n\nAh... A fellow warlock I see. Perhaps we discuss what led to this series of events and maybe we can find out what went wrong?\n\n<Unsure of what to do next, you suggest they return to speak with Doan Karhan.>", sourceObjective = "Meet with Doan Karhan and the Mysterious Traveler in the Barrens.", completion = "Interesting indeed... I set you out to slay a demon; never in my wildest imagination would I have thought you'd return with a friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[78699] = { id = 78699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Bhossca", description = "Description", sourceObjective = "Log", completion = "<A note sits in the chest>\n\nFor {name}. I'll be keeping an \"eye\" out for you.\n\n- C", sourceObjectiveStatus = "unverified-source-field" }
quests[78702] = { id = 78702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raszel Ander", sourceObjective = "Raszel was a friend... One I thought I had lost long ago, from a different time... We were young apprentices back then... Much has changed.\n\nThe result of the ritual might have been a setback, but I believe we can still reform the weapon.\n\nRaszel and I have much to discuss, together we will come up with a plan. I'll send word once we know how to move forward.\n\nIn the meantime, take this. It seems like something you might be interested in.", sourceObjectiveStatus = "unverified-source-field" }
quests[78823] = { id = 78823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of the Desert Skies", description = "The drawing is composed of rough, broad, strokes and seems to depict a large bird of prey. Despite the simple composition, the artist clearly viewed this creature with fear and awe. An expert on big game could likely tell you more.", sourceObjective = "Bring the Primitive Drawing to Hemet Nesingwary in Stranglethorn Vale.", completion = "Well now. This is certainly interesting...", sourceObjectiveStatus = "unverified-source-field" }
quests[78830] = { id = 78830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of the Desert Skies", description = "This drawing reminds me of a story I'd heard on another expedition, not long ago. I was told of a great bird, Gharrik, who reigns over the Badlands as an apex predator.\n\nShe was last spotted northeast of Camp Cagg. Perhaps her nest is somewhere nearby?\n\nYou'll need live bait to draw her out. I'll lend you a cage to catch some. Small wildlife is scarce in the Badlands, so you'll need to find your bait elsewhere.\n\nA quill from Gharrik would make a fine prize. You'd certainly be the talk of the camp.", sourceObjective = "Get a Crimson Trophy Quill from Gharrik in the Badlands. Then, return to Hemet Nesingwary in Stranglethorn Vale.", progress = "How goes the hunt? Surely the bird hasn't got you beat!", completion = "Now there's a feather for your cap! Nicely done, {name}.\n\nYou can rest here for a while, if you like. I'm sure your trek through the desert was arduous.", sourceObjectiveStatus = "unverified-source-field" }
quests[78872] = { id = 78872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[78909] = { id = 78909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shifting Scale Talisman", description = "I'll need a... nominal amount of materials for the talisman. \n\n<N'ora smiles sheepishly at you>", sourceObjective = "Bring N'ora Anyheart the following materials alongside the Handful of Shifting Scales to complete the talisman: A satchel of Strange Dust, five Greater Magic Essence, 2 Small Glimmering Shards and five gold pieces.", progress = "I'll concede that I'm not much of an enchanter, but I think I have a fairly solid grasp on the process. In principle, anyway.", completion = "I wish you the best on your adventures and hope you find your way back to me should you encounter any other wonderous discoveries such as this!", sourceObjectiveStatus = "unverified-source-field" }
quests[78914] = { id = 78914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Vessel", description = "Goblin Engineers have tried to create a synthetic Soul Stone, but their methods were crude to say the least. Regardless of their shortcoming, they are on the right track.\n\nI've heard the Goblins swindled a faction of merchants into buying the rights to the recipe. It's unlikely they know the Soul Vessel by itself holds no magical properties. Surely someone will be interested in parting with the pattern, given enough coin.", sourceObjective = "Now that we have a way to weaken the demon we need a vessel to bind them within. The Burning Blade have overrun ancient elven ruins in southern Desolace, using it as a staging ground to summon demons to Azeroth. \n\nOnce you have found a Soul Vessel meet us in Desolace, there we will complete the ritual.", progress = "With the Bough of Shadows and Soul Vessel we will be ready to begin the ritual.", completion = "Ah, yes... yes. That's exactly what we need.", sourceObjectiveStatus = "unverified-source-field" }
quests[78916] = { id = 78916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Void", description = "The dread beast Aku'mai lies dead.  Hidden amongst the viscera and gore of its swollen corpse is an enormous iridescent pearl teeming with raw Void energy.", sourceObjective = "Bring the Blackfathom Pearl to Dawnwatcher Selgorm in Darnassus.", progress = "{name}, what news do you have from Blackfathom?", completion = "The servant of the Old Gods, Aku'mai, is dead. Such an accomplishment is the stuff of real heroes. \n\nThis object may be the key to much greater understanding of the nature of the Void and its effect on our world, It must be studied at once. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78917] = { id = 78917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Void", description = "The dread beast Aku'mai lies dead.  Hidden amongst the viscera and gore of its swollen corpse is an enormous iridescent pearl teeming with raw Void energy.", sourceObjective = "Bring the Blackfathom Pearl to Bashana Runetotem in Thunder Bluff.", progress = "{name}, what news do you have from Blackfathom?", completion = "The servant of the Old Gods, Aku'mai, is dead. You have done a mighty service for the denizens of Kalimdor with this deed.\n\nThe pearl may also be the key to much greater understanding of the nature of the Void and its effect on our world.  It must be studied at once. Walk with the Earth Mother, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78920] = { id = 78920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.", sourceObjective = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "Ah, hello again {name}.  I was just reading the waves the sea, much like I always do.  What brings you to the outpost?", completion = "This... this is quite the find, {name}.\n\nYou acquired this from Baron Aquanis in Blackfathom, you say?  Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him.  While it would be no surprise if it turned out to be the Twilight's Hammer, our studies will also show how they did it as well.\n\nYou did well in bringing this to me.  Please - take this, along with the Earthen Ring's warmest regards.", sourceObjectiveStatus = "unverified-source-field" }
quests[78921] = { id = 78921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Selgorm in Darnassus, {name}, please.", sourceObjective = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.", progress = "Time is a precious commodity, {class}.\n\nMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.\n\nState your business quickly or be on your way.", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nBy the light! To sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, {name}. I salute you on behalf of the Argent Dawn.", sourceObjectiveStatus = "unverified-source-field" }
quests[78922] = { id = 78922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, {name}, please.", sourceObjective = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", progress = "May the Earthmother be with you, {name}.\n\nPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.", completion = "Kelris has eluded the Argent Dawn for some time.\n\nFor some time they considered him dead or missing.\n\nBy ending his reign you have spared the lives of many innocent people, {name}.\n\nEarthmother be praised! To sacrifice another to a servant of an Old God for personal gain is beyond disgusting!\n\nYou have done a great thing this day. Kelris was a creature of evil and sought to bring the world back to a time of chaos by worshipping such creatures as the Old Gods. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78923] = { id = 78923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge in the Deeps", description = "As you might know, I collect lore.  Old lore.  Powerful lore.  Lore that opens doorways, and lore that can awaken Those Who Sleep.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale.  That place is the old dwelling of long-dead elves.  Elves who held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript.  Do this, and I will not forget it.  Not even after ... the end days.", sourceObjective = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.", progress = "The journey to Ashenvale is long, and your task is not easy.  But if you get me the manuscript, {name}...then your reward will be great.", completion = "You found the manuscript!  What a joyous day this is!  Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!\n\nYour service to us is more than you know, {name}.  But I hope that this gift shows you the gratitude we extend to our allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[78924] = { id = 78924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Thaelrid", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.\n\nMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out and aid Thaelrid for me, {name}.", sourceObjective = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.", sourceObjectiveStatus = "unverified-source-field" }
quests[78925] = { id = 78925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", sourceObjective = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding their presence?", completion = "You are no doubt of brave and noble blood, {name}. The Argent Dawn commends you for your efforts against evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[78926] = { id = 78926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga.\n\n'Tis a long journey, {name}.", sourceObjective = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have traveled far and undoubtedly faced great peril.\n\nYour actions have been selfless. 'Tis for the good of all Azeroth that you help me with my research. I thank you, {name}, for all that you have done.\n\nNow if you'll excuse me I have much work to do....", sourceObjectiveStatus = "unverified-source-field" }
quests[78927] = { id = 78927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance to the Old Gods", description = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, {name}. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done.", sourceObjective = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", completion = "Very good!! Thank you, {name}. We may not have stopped the Twilight's Hammer completely, but at least you have staved off another of their plans to return the Old Gods to power.\n\nWho knows what other plans they have manifesting, but we can rest easy for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[78994] = { id = 78994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Solid Foundation", description = "Reforming the weapon has proven challenging, and it's still unclear how the ritual failed, but I believe we have devised an alternative solution.\n\nTo start we need a sturdy base; a Bough of Shadows.\n\nThese trees are malignant growths of the Emerald Nightmare seeping into our world. It's said they weaken the wills of those around them. This magical property will be the foundation we use to build this weapon.\n\nTo aid your search, take this potion. It will hide you from the Emerald Dragons' minions.", sourceObjective = "The Emerald Dragons protect several portals to the Emerald Dream throughout Azeroth. One of these locations surely has what we need.\n\nOnce you've found a Bough of Shadows return with haste.", progress = "Nobody said this was going to be an easy endeavor, but then again most things worth doing aren't.", completion = "Ah yes, you've found it! Your sanity still seems intact as well, so far so good.", sourceObjectiveStatus = "unverified-source-field" }
quests[79007] = { id = 79007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...and that note you found", description = "The faint radiance of the embers darkening, you stumble across the remnants of a recent fire.\nAmidst the scattered provisions, you discover a blistered note.\n\"Not all that burns is lost. Find the twin land, find the place.\"", sourceObjective = "Charred remains of the note serve as your only guide.", completion = "As you stumble upon the remnants of yet another charred corpse, your gaze falls upon a message secured to a wooden plank.", sourceObjectiveStatus = "unverified-source-field" }
quests[79008] = { id = 79008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...and that note you found", description = "The faint radiance of the embers darkening, you stumble across the remnants of a recent fire.\nAmidst the scattered provisions, you discover a blistered note.\n\"Not all that burns is lost. Find the twin land, find the place.\"", sourceObjective = "Charred remains of the note serve as your only guide.", completion = "As you stumble upon the remnants of yet another charred corpse, your gaze falls upon a message secured to a wooden plank.", sourceObjectiveStatus = "unverified-source-field" }
quests[79077] = { id = 79077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Faith", description = "The Light calls us to justice and protection, but also compassion. Our allies are strangers in our lands and we have a duty to teach them our ways.\nThis Night Elf seeks the Light, but is struggling in his meditation. Would you assist him?", sourceObjective = "Meditate on the Light, then pray with the kneeling elf to share your meditations.", progress = "Yes, {name}?", completion = "The Light works its blessings through you, {name}. Honor it by continuing to share your wisdom with supplicants you meet in your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[79078] = { id = 79078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Faith", description = "This human grasps for Elune's light, but his sight is clouded. Would you assist him?", sourceObjective = "Meditate on Elune, then pray with the kneeling human to share your meditations.", completion = "The Light works its blessings through you, {name}. Honor it by continuing to share your wisdom with supplicants you meet in your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[79079] = { id = 79079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Faith", description = "This poor Forsaken priest can't seem to find a loa who will bargain with him. Maybe you could give him a blessing instead?", sourceObjective = "Meditate on the Loa, then pray with the kneeling Forsaken to share your meditations.", completion = "The undead aren't too popular with the loa, but it's good of you to help this one out. Try to show some pity for them if you meet any more who need help, yeah?", sourceObjectiveStatus = "unverified-source-field" }
quests[79080] = { id = 79080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Faith", description = "This Troll is reflecting on death, but lacks a certain... familiarity with the topic. Please help to clarify his understanding.", sourceObjective = "Meditate on undeath, then pray with the kneeling troll to share your meditations.", progress = "Yes, {name}?", completion = "In my experience, our people are at best a curiosity to the rest of the Horde. Still, sharing our knowledge is a simple way to gain their trust. Keep that in mind along your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[79090] = { id = 79090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repelling Invaders", description = "Some of the Warsong Outriders lie defeated, but the battle still rages...", sourceObjective = "Bring the Warsong Outrider Mark to Felore Moonray, Priestess of the Moon, at the Moonwell base in Ashenvale.", progress = "{name}, what news do you have from the front?", completion = "These Horde invaders still sully our lands and harvest from our sacred wilderness. Continue to drive them out!\n\nThis sacred battle hymn may inspire you to fight them with greater determination. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79091] = { id = 79091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Antonidas: The Unabridged Autobiography", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. You say this is from the Ironforge library? ...I'm sure they won't miss it.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79092] = { id = 79092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Theocritus's Research Journal", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
